-- =========================================================================
-- 033  The core drug catalogue.
--
-- The catalogue held 59 rows. A doctor typing "cetri" got nothing back
-- while Cetirizine sat on her own pharmacy shelf, so the autocomplete -
-- which was fully built and working - had almost nothing to offer.
--
-- 177 molecules and formulations across allopathy, Ayurveda and
-- homeopathy, with 332 pack strengths, chosen for what is actually
-- prescribed rather than for breadth. Generated by
-- scripts/build-catalogue-core.js - edit that, not this.
--
-- THIS IS A TYPING AID. It does not decide a dose, suggest an indication,
-- warn about an interaction or block a prescription. The strengths are
-- the packs these are commonly sold in, so a doctor picks instead of
-- typing. Every clinical decision stays hers.
--
-- INSERT OR REPLACE: re-runnable, and it will not disturb rows loaded
-- from the larger scraped dataset, which carry a different id prefix.
-- =========================================================================

-- The original 59-row demo seed used bare slugs as ids; these use a
-- system prefix, so INSERT OR REPLACE would leave both and a doctor
-- typing "dolo" would see Paracetamol twice. Where a name is covered
-- here, the demo row goes. Only drug_strengths references these ids and
-- it cascades; pharmacy stock stores medicine names as text, so nothing
-- on a shelf is touched.
DELETE FROM drug_catalogue
 WHERE source <> 'tcos-core-catalogue'
   AND LOWER(name) IN ('paracetamol', 'cetirizine', 'levocetirizine', 'amoxicillin', 'amoxicillin + clavulanic acid', 'azithromycin', 'cefixime', 'ciprofloxacin', 'ofloxacin', 'doxycycline', 'metronidazole', 'ibuprofen', 'diclofenac', 'aceclofenac', 'naproxen', 'tramadol', 'pantoprazole', 'omeprazole', 'rabeprazole', 'ranitidine', 'domperidone', 'ondansetron', 'metformin', 'glimepiride', 'sitagliptin', 'insulin glargine', 'telmisartan', 'amlodipine', 'losartan', 'ramipril', 'metoprolol', 'atenolol', 'atorvastatin', 'rosuvastatin', 'clopidogrel', 'aspirin', 'montelukast', 'salbutamol', 'budesonide + formoterol', 'prednisolone', 'deflazacort', 'hydroxyzine', 'fexofenadine', 'chlorpheniramine', 'dextromethorphan', 'ambroxol', 'levothyroxine', 'iron + folic acid', 'calcium + vitamin d3', 'vitamin d3', 'vitamin b12', 'folic acid', 'zinc', 'ors', 'albendazole', 'ivermectin', 'fluconazole', 'clotrimazole', 'mupirocin', 'silver sulfadiazine', 'sucralfate', 'lactulose', 'isabgol', 'amitriptyline', 'gabapentin', 'pregabalin', 'escitalopram', 'alprazolam', 'cetrizine + phenylephrine', 'tranexamic acid', 'misoprostol', 'nifedipine', 'ashwagandha', 'triphala', 'brahmi', 'shatavari', 'guduchi', 'tulsi', 'neem', 'amla', 'haritaki', 'bibhitaki', 'yashtimadhu', 'punarnava', 'guggulu', 'shallaki', 'arjuna', 'manjistha', 'vacha', 'bhringraj', 'kutki', 'methi', 'jatamansi', 'shankhpushpi', 'gokshura', 'vidanga', 'pippali', 'avipattikara churna', 'sitopaladi churna', 'talisadi churna', 'hingvastak churna', 'dashamoola', 'chyawanprash', 'drakshasava', 'ashokarishta', 'dashamularishta', 'arjunarishta', 'kumaryasava', 'saraswatarishta', 'punarnavasava', 'yograj guggulu', 'kaishore guggulu', 'triphala guggulu', 'kanchanar guggulu', 'simhanad guggulu', 'guduchi ghana vati', 'chandraprabha vati', 'arogyavardhini vati', 'sanjivani vati', 'khadiradi vati', 'lakshmivilas rasa', 'tribhuvankirti rasa', 'ksheerabala taila', 'mahanarayan taila', 'dhanwantharam taila', 'bala taila', 'anu taila', 'bra